-- V2 users: authentication and account state (DATABASE_ERD section 3.1).
--
-- Identifiers are generated by the application (ADR-002), so id has no database
-- default. Email is normalized (trimmed and lowercased) before storage, so the
-- UNIQUE constraint enforces case-insensitive uniqueness in practice, including
-- under concurrent registration.
--
-- enabled means the account is active and may authenticate. It is NOT the
-- verification flag. email_verified_at is a separate authorization gate for
-- protected spaces and stays NULL until the user verifies their email (ADR-005).
CREATE TABLE users (
    id                UUID         NOT NULL,
    email             VARCHAR(255) NOT NULL,
    password_hash     VARCHAR(255) NOT NULL,
    email_verified_at TIMESTAMPTZ  NULL,
    enabled           BOOLEAN      NOT NULL DEFAULT TRUE,
    created_at        TIMESTAMPTZ  NOT NULL,
    updated_at        TIMESTAMPTZ  NOT NULL,
    CONSTRAINT pk_users PRIMARY KEY (id),
    CONSTRAINT uq_users_email UNIQUE (email)
);
